import { describe, it, expect } from "vitest";
import setupJson from "./connector-setup.json";
import { connectors } from "./connectors";
import type { ConnectorSetup } from "./connectorSetup";

// The JSON is generated by sync-connector-setup.mjs, keyed by connector name.
const setup = setupJson as unknown as Record<string, ConnectorSetup>;

describe("connector-setup snapshot", () => {
  it("has setup data for most of the web catalog", () => {
    const covered = connectors.filter((c) => setup[c.name]).length;
    expect(covered).toBeGreaterThan(connectors.length * 0.8);
  });

  it("carries the slack_webhook boundary, secret field and 4-step guide", () => {
    const s = setup.slack_webhook;
    expect(s.outboundOnly).toBe(true);
    expect(s.fields?.[0].kind).toBe("secret");
    expect(s.guide).toHaveLength(4);
    expect(s.guide?.[0]).not.toMatch(/^\d+\./);
  });

  it("only links https docs and never stores placeholder or value text", () => {
    for (const [name, s] of Object.entries(setup)) {
      if (s.docsUrl) expect(s.docsUrl, name).toMatch(/^https:\/\//);
      for (const f of s.fields ?? []) expect(Object.keys(f).sort().every((k) => ["label", "kind", "optional", "help"].includes(k)), name).toBe(true);
    }
  });
});
